<?php
namespace App\Game; use App\DB; use App\Telegram;
final class EventService { private const POOL=['mystery_message'=>['w'=>20,'min_level'=>1],'found_money'=>['w'=>25,'min_level'=>1],'expensive_bill'=>['w'=>25,'min_level'=>1]];
 public function maybeTrigger(array $u):void{if(random_int(1,100)>25)return;$s=DB::pdo()->prepare('SELECT COUNT(*) FROM pending_events WHERE user_id=? AND expires_at>?');$s->execute([$u['id'],time()]);if((int)$s->fetchColumn()>0)return;$pool=array_filter(self::POOL,fn($e)=>(int)$u['level']>=$e['min_level']);$total=array_sum(array_column($pool,'w'));$roll=random_int(1,$total);foreach($pool as $k=>$e){$roll-=$e['w'];if($roll<=0){$this->fire($u,$k);break;}}}
 private function fire(array $u,string $k):void{$data=match($k){'mystery_message'=>['text'=>'📩 <b>پیام ناشناس</b>\n\nیه پیشنهاد دارم که ممکنه زندگیت رو عوض کنه.','options'=>['reply'=>['label'=>'💬 جواب بده','effect'=>['influence'=>5,'cash'=>300]],'ignore'=>['label'=>'🙈 نادیده بگیر','effect'=>['happiness'=>2]]]],'found_money'=>['text'=>'🎲 یه کیف قدیمی پیدا کردی؛ داخلش ۸۰۰ دلار بود!','options'=>['keep'=>['label'=>'💰 برش دارم','effect'=>['cash'=>800,'fame'=>-3]],'give'=>['label'=>'🤲 به نیازمند بدم','effect'=>['happiness'=>10,'fame'=>12]]]],'expensive_bill'=>['text'=>'⚠️ یه قبض ناگهانی ۵۰۰ دلاری اومده!','options'=>['pay'=>['label'=>'💸 پرداخت می‌کنم','effect'=>['cash'=>-500]],'dodge'=>['label'=>'😈 فرار می‌کنم','effect'=>['fame'=>-10,'health'=>-5]]]],default=>null};if(!$data)return;DB::pdo()->prepare('INSERT INTO pending_events (user_id,event_key,data,expires_at,created_at) VALUES (?,?,?,?,?)')->execute([$u['id'],$k,json_encode($data,JSON_UNESCAPED_UNICODE),time()+86400,time()]);$rows=[];foreach($data['options'] as $ok=>$o)$rows[]=[Telegram::btn($o['label'],"evt:$k:$ok")];Telegram::sendMessage((int)$u['telegram_id'],$data['text'],Telegram::kb($rows));}
 public function resolve(array $u,string $eventKey,string $optKey):void{$s=DB::pdo()->prepare('SELECT * FROM pending_events WHERE user_id=? AND event_key=? AND expires_at>? ORDER BY id DESC LIMIT 1');$s->execute([$u['id'],$eventKey,time()]);$ev=$s->fetch();if(!$ev){Telegram::sendMessage((int)$u['telegram_id'],'⌛ این رویداد منقضی شده.');return;}$data=json_decode($ev['data'],true);$opt=$data['options'][$optKey]??null;if(!$opt)return;$pdo=DB::pdo();$pdo->beginTransaction();try{$fresh=PlayerService::findByTg((int)$u['telegram_id'])??$u;$fields=[];$delta=[];foreach(($opt['effect']??[]) as $stat=>$v){$v=(int)$v;$delta[]=( $v>=0?'➕ ':'➖ ').$stat.' '.abs($v);if($stat==='cash'){$new=(int)$fresh['cash']+$v;if($new<0)throw new \RuntimeException('not_enough_money');$fields['cash']=$new;}elseif(in_array($stat,['fame','power','influence','happiness','health'],true))$fields[$stat]=max(0,(int)$fresh[$stat]+$v);}if($fields)PlayerService::update((int)$u['id'],$fields);$pdo->prepare('DELETE FROM pending_events WHERE id=?')->execute([$ev['id']]);$pdo->commit();Telegram::sendMessage((int)$u['telegram_id'],'✅ تصمیمت ثبت شد.\n\n'.implode("\n",$delta));}catch(\Throwable $e){if($pdo->inTransaction())$pdo->rollBack();Telegram::sendMessage((int)$u['telegram_id'],'❌ انجام نشد: '.$e->getMessage());}}
}
